begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to authenticated,anon;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values
('50000000-0000-4000-8000-000000000001','admin@phase5.test','{"nome":"Admin Cinco","tipo":"sindico","cidade":"São Paulo","estado":"SP","termos":true,"termos_versao":"2026-10-19","privacidade_versao":"2026-10-19"}'),
('50000000-0000-4000-8000-000000000002','owner@phase5.test','{"nome":"Dono Cinco","tipo":"fornecedor","empresa":"Empresa Cinco","cnpj":"11222333000181","telefone":"11999999999","termos":true,"termos_versao":"2026-10-19","privacidade_versao":"2026-10-19"}'),
('50000000-0000-4000-8000-000000000003','sales@phase5.test','{"nome":"Comercial Cinco","tipo":"sindico","cidade":"São Paulo","estado":"SP","termos":true,"termos_versao":"2026-10-19","privacidade_versao":"2026-10-19"}');
insert into public.user_roles(user_id,role) values('50000000-0000-4000-8000-000000000001','admin'),('50000000-0000-4000-8000-000000000003','comercial');
select set_config('test.sid',(select id::text from public.fornecedores where dono_id='50000000-0000-4000-8000-000000000002'),true);
update public.fornecedores set logo_url='https://example.com/logo.webp',descricao_curta='Descrição da empresa',whatsapp='11999998888',status='em_analise' where id=current_setting('test.sid')::uuid;
insert into public.fornecedor_segmentos(fornecedor_id,segmento_id) select current_setting('test.sid')::uuid,id from public.segmentos where slug='elevadores';
