select set_config('test.row','[{"linha":2,"nome_fantasia":"Importada Exemplo","cnpj":"04252011000110","segmento":"Elevadores","cidade":"São Paulo","uf":"SP","whatsapp":"11999998888","email":"dono.importado@example.com","site":"https://example.com","instagram":"exemplo"},{"linha":3,"nome_fantasia":"Inválida","cnpj":"123","segmento":"Inexistente","cidade":"Cidade Inválida","uf":"SP","whatsapp":"11999998888"}]',true);
set local role anon;
select throws_ok($$select public.admin_listar('fornecedores')$$,'42501',null,'visitante não chama administração');
select throws_ok($$select public.admin_agir('fornecedores',current_setting('test.sid')::uuid,'aprovar')$$,'42501',null,'visitante não aprova');
reset role;set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.admin_listar('fornecedores')$$,'P0001','Acesso administrativo negado','fornecedor não lista administração');
select throws_ok($$select public.admin_agir('fornecedores',current_setting('test.sid')::uuid,'aprovar')$$,'P0001','Acesso administrativo negado','fornecedor não se aprova');
