select lives_ok($$select public.admin_listar('fornecedores')$$,'comercial lê fornecedores');
select throws_ok($$select public.admin_listar('usuarios')$$,'P0001','Acesso administrativo negado','comercial não lista usuários');
select throws_ok($$select public.admin_agir('fornecedores',current_setting('test.sid')::uuid,'suspender','{"motivo":"Motivo suficiente"}')$$,'P0001','Acesso administrativo negado','comercial não altera status');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.admin_listar('dashboard')$$,'admin recebe indicadores');
select lives_ok($$select public.admin_listar('usuarios')$$,'admin lista usuários com papéis');
select throws_ok($$select public.admin_agir('fornecedores',current_setting('test.sid')::uuid,'aprovar')$$,'P0001','Conclua o checklist de revisão','aprovação exige checklist');
select lives_ok($$select public.admin_agir('fornecedores',current_setting('test.sid')::uuid,'aprovar','{"checklist":{"logo":true,"texto":true,"cnpj":true,"fotos":true,"segmentos":true}}')$$,'admin aprova com checklist');
select is((public.admin_listar('fornecedores')->'items'->0->>'status'),'publicado','aprovação publica');
reset role;
select ok((select teste_fim-teste_inicio=interval '90 days' from public.fornecedores where id=current_setting('test.sid')::uuid),'teste inicial dura 90 dias');
select set_config('test.end',(select teste_fim::text from public.fornecedores where id=current_setting('test.sid')::uuid),true);
set local role authenticated;
select throws_ok($$select public.admin_agir('fornecedores',current_setting('test.sid')::uuid,'ajuste','{"motivo":"curto"}')$$,'P0001','Informe um motivo de 10 a 2000 caracteres','ajuste exige motivo suficiente');
select lives_ok($$select public.admin_agir('fornecedores',current_setting('test.sid')::uuid,'suspender','{"motivo":"Revisão documental necessária"}')$$,'admin suspende');
select is(public.fornecedor_publico((public.admin_listar('fornecedores')->'items'->0->>'slug'))->>'fornecedor',null,'suspensão remove publicação');
select lives_ok($$select public.admin_agir('fornecedores',current_setting('test.sid')::uuid,'reativar')$$,'reativação volta à análise');
select lives_ok($$select public.admin_agir('fornecedores',current_setting('test.sid')::uuid,'aprovar','{"checklist":{"logo":true,"texto":true,"cnpj":true,"fotos":true,"segmentos":true}}')$$,'nova aprovação possível');
reset role;
select is((select teste_fim::text from public.fornecedores where id=current_setting('test.sid')::uuid),current_setting('test.end'),'nova aprovação não reinicia teste');
set local role authenticated;
select is(public.admin_importar(current_setting('test.row')::jsonb)->0->>'status','valido','CSV válido indicado na prévia');
select is(public.admin_importar(current_setting('test.row')::jsonb)->1->>'status','erro','CSV inválido aponta erro na linha');
select lives_ok($$select public.admin_importar(current_setting('test.row')::jsonb,true,'51000000-0000-4000-8000-000000000001',true)$$,'importação cria válidos e convite');
select lives_ok($$select public.admin_importar(current_setting('test.row')::jsonb,true,'51000000-0000-4000-8000-000000000001',true)$$,'retry do lote é idempotente');
reset role;
select is((select count(*) from public.fornecedores where cnpj='04252011000110'),1::bigint,'importação não duplica CNPJ');
select ok((select dono_id is null and status='rascunho' from public.fornecedores where cnpj='04252011000110'),'importação cria rascunho sem dono');
select is((select count(*) from public.convites_proprietario),1::bigint,'convite de proprietário criado uma vez');
select ok((select expira_em-criado_em=interval '14 days' from public.convites_proprietario),'convite expira em 14 dias');
select ok(exists(select 1 from public.audit_log where acao='IMPORTACAO_CSV'),'importação auditada');
set local role authenticated;
select throws_ok($$select public.admin_agir('usuarios','50000000-0000-4000-8000-000000000001','ativo','{"valor":false}')$$,'P0001','O último admin ativo não pode ser desativado','último admin não desativa');
select throws_ok($$select public.admin_agir('usuarios','50000000-0000-4000-8000-000000000001','papel','{"papel":"admin","valor":false}')$$,'P0001','O último admin ativo não pode ser removido','último admin não perde papel');
select lives_ok($$select public.admin_agir('fornecedores',current_setting('test.sid')::uuid,'leitura')$$,'visualização de fornecedor disponível somente leitura');
reset role;
select ok(exists(select 1 from public.audit_log where acao='VISUALIZACAO_FORNECEDOR'),'visualização auditada');
select set_config('test.owner_token',(select payload->>'token' from public.email_outbox where template='convite_proprietario' limit 1),true);
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.aceitar_propriedade(current_setting('test.owner_token'))$$,'P0001','Entre com o mesmo e-mail do convite','convite não aceita outro e-mail');
reset role;
insert into auth.users(id,email,raw_user_meta_data) values('50000000-0000-4000-8000-000000000004','dono.importado@example.com','{"nome":"Novo Dono Importado","tipo":"fornecedor","empresa":"Importada Exemplo","cnpj":"04252011000110","telefone":"11999999999","termos":true,"termos_versao":"2026-10-19","privacidade_versao":"2026-10-19"}');
select is((select count(*) from public.fornecedores where cnpj='04252011000110'),1::bigint,'cadastro do convidado não duplica rascunho sem dono');
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000004',true);
select lives_ok($$select public.aceitar_propriedade(current_setting('test.owner_token'))$$,'convidado aceita propriedade da página');
select throws_ok($$select public.aceitar_propriedade(current_setting('test.owner_token'))$$,'P0001','Convite inválido ou expirado','convite de proprietário é de uso único');
reset role;
select is((select dono_id from public.fornecedores where cnpj='04252011000110'),'50000000-0000-4000-8000-000000000004'::uuid,'propriedade vinculada ao convidado');
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.admin_agir('fornecedores',current_setting('test.sid')::uuid,'creditos','{"quantidade":3,"motivo":"Cortesia operacional registrada pelo admin"}')$$,'admin registra ajuste de créditos');
select lives_ok($$select public.admin_agir('segmentos',(select id from public.segmentos where slug='elevadores'),'salvar','{"nome":"Elevadores e plataformas","grupo":"estrutura","ordem":4,"ativo":true}')$$,'admin renomeia especialidade');
select is(public.redirecionamento_segmento('elevadores'),'elevadores-e-plataformas','slug anterior redireciona para a especialidade ativa');
reset role;
select ok(exists(select 1 from public.audit_log where tabela='creditos_extrato' and acao='INSERT'),'ajuste de créditos auditado');
set local role authenticated;
select lives_ok($$select public.admin_agir('usuarios','50000000-0000-4000-8000-000000000002','redefinir_senha')$$,'admin exige nova senha do usuário');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select is(public.obter_fornecedor(current_setting('test.sid')::uuid),null::jsonb,'senha pendente bloqueia acesso aos dados privados da empresa');
select throws_ok($$update public.profiles set senha_pendente=false where id=auth.uid()$$,'P0001','Campo protegido','usuário não remove exigência de senha por atualização direta');
reset role;
update auth.users set encrypted_password='novo_hash_auth_server' where id='50000000-0000-4000-8000-000000000002';
select is((select senha_pendente from public.profiles where id='50000000-0000-4000-8000-000000000002'),false,'alteração real da senha libera a conta');
select * from finish();rollback;
